// ─── Configuration ────────────────────────────────────────────────────────
// Everything you normally tweak lives here.

const OUTPUT_DIR    = '/data/youtube';                 // must be a volume on the n8n host
const ARCHIVE_FILE  = '/data/youtube/.downloaded.txt'; // yt-dlp keeps ids here so nothing downloads twice
const MAX_HEIGHT    = 1080;

// SponsorBlock categories to act on. Full list:
// sponsor, selfpromo, interaction, intro, outro, preview, filler, music_offtopic
const SB_CATEGORIES = 'sponsor,selfpromo,interaction,intro,outro,preview,music_offtopic';

// true  -> segments are cut out of the file (re-encodes around the cuts, slower)
// false -> segments are only written as chapters, so a player can skip them
const REMOVE_SEGMENTS = true;

// Paste a single URL here to try the workflow with the Manual trigger.
const MANUAL_URL = '';

// ─── Safety: nothing from the feed reaches the shell verbatim ──────────────
// POSIX single-quote escaping.
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

// A YouTube video id is exactly 11 chars from this alphabet. We rebuild the URL
// from the id we extracted, we never forward a string the feed gave us.
const VIDEO_ID = /^[A-Za-z0-9_-]{11}$/;
const EMBEDDED = /(?:v=|\/shorts\/|\/embed\/|youtu\.be\/|yt:video:)([A-Za-z0-9_-]{11})/;

function extractId(fields) {
  for (const candidate of fields) {
    if (!candidate) continue;
    const s = String(candidate);
    if (VIDEO_ID.test(s)) return s;
    const m = s.match(EMBEDDED);
    if (m) return m[1];
  }
  return null;
}

const sbFlag = REMOVE_SEGMENTS
  ? '--sponsorblock-remove ' + q(SB_CATEGORIES) + ' --force-keyframes-at-cuts'
  : '--sponsorblock-mark ' + q(SB_CATEGORIES);

const results = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const id = extractId([
    j.videoId, j['yt:videoId'], j.id, j.link, j.url, j.guid, MANUAL_URL,
  ]);

  // An entry we cannot parse is skipped, not guessed at.
  if (!id) continue;

  const url = 'https://www.youtube.com/watch?v=' + id;

  const command = [
    'mkdir -p ' + q(OUTPUT_DIR) + ' &&',
    'yt-dlp',
    '--ignore-config',
    '--download-archive ' + q(ARCHIVE_FILE),
    '--quiet --no-progress --no-warnings',
    '-f ' + q('bv*[height<=' + MAX_HEIGHT + ']+ba/b[height<=' + MAX_HEIGHT + ']'),
    '--merge-output-format mkv',
    sbFlag,
    '--embed-metadata --embed-chapters --embed-thumbnail',
    '-o ' + q(OUTPUT_DIR + '/%(uploader)s/%(upload_date)s - %(title)s [%(id)s].%(ext)s'),
    '--print after_move:filepath',
    q(url),
  ].join(' ');

  results.push({
    json: {
      videoId: id,
      url,
      title: j.title ?? null,
      channel: j.author ?? j['media:group']?.['media:credit'] ?? null,
      command,
    },
  });
}

return results;
